      'beginner.res.intro': '游戏中有三种核心资源：许愿星（稀缺）、金币（可赚）、时间（有限）。每一类都有优先级——花对地方事半功倍。',
      'beginner.res.star.h3': '⭐ 许愿星消费优先级',
      'beginner.res.star.t1.h': '🥇 第一优先：背包 & 仓库扩容（前 5 次）',
      'beginner.res.star.t1.p': '前 5 次背包 +10 格、仓库 +50 格各仅需 <strong>10 许愿星</strong>（原价 25，相当于 6 折）。这是全游戏最值的投资——背包空间直接影响采集和钓鱼效率。找 NPC Ka Ching（西北郊区 8 号地块对面）购买。共需 <strong>50 星 = +50 背包 + 250 仓库</strong>。第 6 次起涨到 25 星/次，性价比骤降，暂时不要继续买。',
      'beginner.res.star.t2.h': '🥈 第二优先：爱好解锁 & 烹饪升级',
      'beginner.res.star.t2.p': '钓鱼(Lv.2 自动)、园艺(Lv.3 自动)不需要花许愿星。烹饪(Lv.5 用爱好扩展券)是第一个需要决策的——必选。后续捕虫(Lv.8)、观鸟(Lv.11)各需要一张扩展券。<strong>烹饪爱好等级越高 → 出高星概率越大 → 同样材料多赚 50-100%。</strong>',
      'beginner.res.star.t3.h': '🥉 第三优先：功能性建筑 & 家具',
      'beginner.res.star.t3.p': '额外炉灶（多一个灶 = 烹饪效率 ×1.3）、更多田地、功能性储物家具。这些直接提升赚钱效率，属于「花钱赚钱」的投资型消费。<strong>多一个炉灶意味着每天多产 3-5 份菜品，约 +1,000-1,500G/天。</strong>',
      'beginner.res.star.t4.h': '💡 应急用途 & 绝对不花的地方',
      'beginner.res.star.t4.p': '<strong>应急：</strong>1 星换冲天炮 → 卖 Albert Jr. = 1,100G（不建议频繁使用，许愿星比金币珍贵得多）<br><strong>❌ 绝对不要：</strong>加速作物生长（2 小时不值 1 星）、购买基础原料（种/钓/采集免费获得）、纯装饰物品（DG Lv.15 高级建造后再考虑）、加速宠物/爱好进度',
      'beginner.res.time.c1.h': '🔴 最高优先',
      'beginner.res.time.c1.p': '\n          <strong>每日 5 个居民任务</strong>（必做！）<br>\n          金币 + 许愿星 + 贡献勋章<br>\n          效率：10 分钟 ≈ 7,000G + 2-5 星<br>\n          <span style="color:var(--coral)">不可跳过，DG 经验唯一来源</span>\n        ',
      'beginner.res.time.c2.h': '🟡 高优先',
