      'beginner.res.time.c3.h': '🟢 中优先',
      'beginner.res.time.c3.p': '\n          <strong>免费采集扫荡</strong><br>\n          浆果、蘑菇、香草、水果<br>\n          效率：2 分钟 ≈ 200-500G（零成本）<br>\n          <strong>低价值点钓鱼</strong>（河流·全年）<br>\n          效率：灵活，囤食材等烹饪\n        ',
