      'dbfish.guide.rule100.p': '<strong>超过 100 金币的鱼直接卖给 Albert Jr.</strong>，<strong>其余留作烹饪</strong>——沙丁鱼（40 金币）做成炸鱼薯条值 310 金币，鲫鱼（80 金币）做成炸鲫鱼值 350 金币。唯一例外：帝王蟹清蒸后价值更高（1100 金币）。',
      'dbfish.guide.tip.h': '🚀 进阶技巧',
      'dbfish.guide.t1.h': '💐 彩虹花束留到平时用',
      'dbfish.guide.t1.p': '彩虹天气本身就极高概率刷稀有鱼种，把彩虹花束留到普通天气使用，等于白赚一个「迷你彩虹日」。',
      'dbfish.guide.t2.h': '✨ 金色鱼影是头奖',
