      'dbfish.guide.t3.h': '🎣 在渔具店附近钓鱼',
      'dbfish.guide.t3.p': '在渔村码头钓鱼最省心——紧挨渔具店，方便买鱼饵和修工具，而且全年全天可钓。',
      'dbinsects.help': '🦋 昆虫图鉴使用说明',
      'dbinsects.helpText': '每个条目都标注了昆虫出现的地点和时间，以及所需的天气和稀有度。按名称搜索或按稀有度逐级浏览，找出你还没收集到的品种。<strong>快速提示：</strong>独角仙和蓝色闪蝶是诱饵活动限定，多数蝴蝶只在晴朗的白天出现——请合理安排捕捉时间。',
      // 捕虫攻略（昆虫图鉴标题下方）
      'dbinsects.guide.eyebrow': '🦋 捕虫攻略',
      'dbinsects.guide.h2': '从入门到精通：<strong style="color:var(--green)">捕虫</strong>攻略',
      'dbinsects.guide.intro': '挥网之前你需要知道的一切：解锁条件、工具、最佳捕虫点、天气窗口，以及全岛最稀有的昆虫。',
      'dbinsects.guide.rules': '<strong>🦋 记住三条规则：</strong> ❶ DG 等级达到 8 级后，用爱好扩展券找 Naniwa 解锁捕虫 &nbsp; ❷ 67 种昆虫分布在森林 / 花田 / 温泉山 &nbsp; ❸ 多数稀有昆虫只在特定天气出现——出发前先看天气',
      'dbinsects.guide.g1.h': '🦋 解锁与第一张捕虫网',
      'dbinsects.guide.g1.p': 'DG 等级达到 8 级后，用爱好扩展券选择捕虫，导师 Naniwa（城镇中心）会为你准备好捕虫网。捕虫是收藏型爱好，不产出金币，建议先解锁烹饪再补捕虫。',
      'dbinsects.guide.g2.h': '🛠️ 捕虫网与充气诱捕器',
      'dbinsects.guide.g2.p': '在 Naniwa 的商店购买捕虫网和充气昆虫诱捕器。诱捕器能被动吸引苏氏闪蝶等限定品种，其他昆虫则需要你主动挥网捕捉。',
      'dbinsects.guide.g3.h': '🎯 慢慢靠近 + 看清天气',
      'dbinsects.guide.g3.p': '装备捕虫网后慢慢靠近昆虫——走太快会惊跑它们。出发前先看天气：许多蝴蝶只在晴天出现，彩虹天气会解锁多个限定品种。',
      'dbinsects.guide.w.h3': '去哪儿捕虫',
      'dbinsects.guide.flower.h': '🌸 花田',
      'dbinsects.guide.flower.p': '昆虫最丰富的区域——蝴蝶（孔雀蛱蝶、紫皇蛱蝶、珍珠蝶）、蜜蜂和花金龟都聚集于此，晴天出没最多。',
      'dbinsects.guide.forest.h': '🌲 森林与森林岛',
      'dbinsects.guide.forest.p': '夜间捕虫首选——独角仙（400 金币）、锹甲和蛾类在夜幕降临后出现在树干上。森林岛在彩虹天气还会出现高山天牛。',
      'dbinsects.guide.mountain.h': '♨️ 温泉山与其他区域',
      'dbinsects.guide.mountain.p': '螳螂、宝石金龟和蜻蜓分布在温泉山、渔村、郊区和你的家园——跑一遍这些区域，就能补齐图鉴的大部分。',
      'dbinsects.guide.wst.h3': '天气 · 季节 · 时间',
      'dbinsects.guide.weather.h': '🌦️ 天气',
      'dbinsects.guide.weather.p': '彩虹天气解锁多个限定品种——彩虹锹甲、赤色沼泽蜻、高山天牛和天蓝木蜂<strong>只在彩虹天气</strong>出现。晴天适合捕蝴蝶，雨天蜻蜓更多。',
      'dbinsects.guide.season.h': '🍂 季节',
      'dbinsects.guide.season.p': '昆虫只在春、夏、秋三季出现——冬天一只都没有。夏季是最繁忙的季节，大多数甲虫和蝴蝶都在此时活跃。',
      'dbinsects.guide.time.h': '🌙 时间',
      'dbinsects.guide.time.p': '蝴蝶和蜜蜂白天活动；蛾类、萤火虫和独角仙夜间出没。黄昏和黎明能遇到黄缘蛱蝶等晨昏性品种。',
      'dbinsects.guide.hv.h3': '💰 高价值目标',
      'dbinsects.guide.hv.intro': '值得专门跑一趟的昆虫——出发前先看好出没条件。',
