      'dbrecipes.guide.rules': '<strong>🍳 记住三条规则：</strong> ❶ DG 等级达到 5 级后，用爱好扩展券找 Massimo 解锁烹饪 &nbsp; ❷ 96 道食谱分为加工 / 烹饪 / 甜点 / 饮品 / 活动五类 &nbsp; ❸ 廉价食材先加工再卖，别直接卖原材料',
