      'dbrecipes.guide.hv.r3.name': '烛光晚餐', 'dbrecipes.guide.hv.r3.unlock': '烹饪 9 级 · Massimo 商店',
      'dbrecipes.guide.hv.r4.name': '露营套餐', 'dbrecipes.guide.hv.r4.unlock': '烹饪 7 级 · Massimo 商店',
      'dbrecipes.guide.hv.r5.name': '清蒸帝王蟹', 'dbrecipes.guide.hv.r5.unlock': '烹饪 10 级 · Massimo 商店',
      'dbrecipes.guide.hv.r6.name': '帝王蟹意面', 'dbrecipes.guide.hv.r6.unlock': '烹饪 12 级',
      'dbrecipes.guide.hv.r7.name': '精致下午茶宴', 'dbrecipes.guide.hv.r7.unlock': '烹饪 12 级 · Massimo 商店',
      'dbrecipes.guide.hv.r8.name': '黑松露奶油意面', 'dbrecipes.guide.hv.r8.unlock': '烹饪 11 级 · Massimo 商店',
      'dbrecipes.guide.hv.r9.name': '起司虾仁炸虾钳', 'dbrecipes.guide.hv.r9.unlock': '烹饪 13 级 · Massimo 商店',
      'dbrecipes.guide.rule.h': '🥫 利润法则：先加工，别卖原材料',
      'dbrecipes.guide.rule.p': '<strong>永远别把廉价食材直接卖掉。</strong>4 颗蓝莓（64 金币）能做成蓝莓酱（170–320 金币），任意廉价鱼加土豆能做成炸鱼薯条（310–620 金币）——同样的食材，利润翻 2–5 倍。超过 100 金币的高价鱼直接卖，更便宜的留作烹饪。唯一例外：帝王蟹清蒸（1100 金币）比生卖（600 金币）划算得多。',
      'dbrecipes.guide.tip.h': '🚀 进阶技巧',
      'dbrecipes.guide.t1.h': '🫐 睡前种蓝莓',
      'dbrecipes.guide.t1.p': '蓝莓 6 小时成熟——睡前种下、醒来收获，白天做成蓝莓酱（170 金币+），形成完美循环。',
      'dbrecipes.guide.t2.h': '🔥 四灶批量烹饪',
      'dbrecipes.guide.t2.p': '让 4 口炉灶同时做同一种菜——蓝莓酱、炸鱼薯条或炸鲫鱼——无需额外操作即可成倍产出。',
      'dbrecipes.guide.t3.h': '📅 别错过活动食谱',
      'dbrecipes.guide.t3.p': '寻鲸季料理（海洋盛宴 1600 金币）、三丽鸥联动可丽饼（扭蛋机）以及隐藏的雏菊花茶 / 玫瑰花茶都是限时的，趁活动期间抓紧解锁。',
      'dbrecipes.help': '🍳 食谱大全使用说明',
      'dbrecipes.helpText': '每道食谱都列出了材料、能量、售价和净利润，方便你比较哪些菜值得批量烹饪。按利润率排序即可找到每天最赚钱的菜。<strong>快速提示：</strong>炸鱼薯条（313% 利润率）和蔬菜杂烩（456% 利润率）是每日批量首选，清蒸帝王蟹则以 1100 金币位居售价榜首。',
      'dbcrops.help': '🌱 作物图鉴使用说明',
      'dbcrops.helpText': '对比 28 种作物的生长时间、季节适配度和每小时收益，规划最高效的农田；优先级一栏标出了最佳种植选择。<strong>快速提示：</strong>土豆前期收益是番茄的 3 倍，蓝莓睡前种下、早上起床就能收获。',
      // 作物攻略（作物图鉴标题下方）
      'dbcrops.guide.eyebrow': '🌱 作物攻略',
      'dbcrops.guide.h2': '从入门到精通：<strong style="color:var(--green)">种田</strong>攻略',
      'dbcrops.guide.intro': '播下第一颗种子前你需要知道的一切：解锁条件、农耕等级、季节适配、浇水机制，以及全岛最值钱的作物。',
      'dbcrops.guide.rules': '<strong>🌱 记住三条规则：</strong> ❶ DG 等级达到 3 级后，导师 Blanc 解锁园艺 &nbsp; ❷ 雨天会自动浇水 &nbsp; ❸ 便宜的作物加工成料理——蓝莓和土豆价值能翻 3–5 倍',
      'dbcrops.guide.g1.h': '🌱 解锁与第一批种子',
      'dbcrops.guide.g1.p': 'DG 等级达到 3 级后，导师 Blanc（城镇中心附近）解锁园艺。先买土豆种子——新手期最佳作物，收益是番茄的 3 倍。',
      'dbcrops.guide.g2.h': '📈 看懂生长时间',
      'dbcrops.guide.g2.p': '土豆 2 小时熟（白天可轮作多轮），蓝莓 6 小时（睡前种），小麦 4 小时。合理安排播种时间，让作物在你起床时正好成熟。',
      'dbcrops.guide.g3.h': '🎯 优先级一栏',
      'dbcrops.guide.g3.p': '图鉴标出了最佳种植选择——<strong>最高</strong>（小麦、黑松露）、<strong>高</strong>（土豆、蓝莓等）、普通与低。优先种高优先级作物赚钱，再留几样便宜作物当任务储备。',
      'dbcrops.guide.w.h3': '该种什么',
      'dbcrops.guide.grain.h': '🌾 谷物',
      'dbcrops.guide.grain.p': '小麦（4 小时）是基础——几乎所有高利润食谱都需要，DG Lv.5 起批量种植。玉米（40 金币）和大豆（28 金币）是夏季强档。',
      'dbcrops.guide.veg.h': '🥔 蔬菜',
      'dbcrops.guide.veg.p': '土豆是前期赚钱之王（35 金币、2 小时、全年可种）。番茄和生菜是便宜的任务填充；南瓜（55 金币）是秋季赚钱作物。',
      'dbcrops.guide.fruit.h': '🍓 水果与采集',
      'dbcrops.guide.fruit.p': '蓝莓 → 果酱是经典利润循环（4 颗 → 170 金币以上）。西瓜（80 金币）和菠萝（120 金币）是夏季高产值；黑松露（200 金币）是秋季稀有采集。',
      'dbcrops.guide.wst.h3': '季节 · 浇水 · 收获',
      'dbcrops.guide.season.h': '🍂 季节',
      'dbcrops.guide.season.p': '土豆、小麦、胡萝卜、洋葱、白菜和柠檬全年可种。其他大多有季节限制——水稻和黄瓜春夏季、玉米和茄子夏秋季、南瓜仅秋季。',
      'dbcrops.guide.watering.h': '🌧️ 浇水与雨天',
      'dbcrops.guide.watering.p': '雨天会自动浇水——雨天可以省掉手动浇水。睡前看天气预报：雨夜意味着第二天醒来田地已浇好、作物可收。',
      'dbcrops.guide.harvest.h': '🧺 收获类型',
