      'dbnpcs.help': '👥 NPC 图鉴使用说明',
      'dbnpcs.helpText': '查找每一位居民、导师和商人，了解他们的位置、每日作息、解锁条件和喜好礼物。按名称搜索即可定位特定角色。<strong>快速提示：</strong>导师按顺序解锁——Vanya（Lv.2 钓鱼）、Blanc（Lv.3 园艺）、Massimo（Lv.5 烹饪）——送出稀有物品前先查看礼物偏好。',
      // NPC攻略（NPC图鉴标题下方）
      'dbnpcs.guide.eyebrow': '👥 NPC攻略',
      'dbnpcs.guide.h2': '从入门到精通：<strong style="color:var(--coral)">认识全岛 NPC</strong>',
      'dbnpcs.guide.intro': '关于岛上 20 位居民、导师和商人，你需要知道的一切：解锁顺序、送礼、好感度，以及哪些角色对你的进度最关键。',
      'dbnpcs.guide.rules': '<strong>👥 记住三条规则：</strong> ❶ 导师按顺序解锁爱好——Vanya（Lv.2）→ Blanc（Lv.3）→ Massimo（Lv.5） &nbsp; ❷ 每天送喜欢的礼物，好感度涨得快 &nbsp; ❸ 优先买满 Ka Ching 的背包扩容折扣',
      'dbnpcs.guide.g1.h': '🎓 导师解锁你的爱好',
      'dbnpcs.guide.g1.p': '五位导师对应五大生产爱好：Vanya（钓鱼，DG Lv.2）、Blanc（园艺，Lv.3）、Massimo（烹饪，Lv.5）、Naniwa（捕虫，Lv.8）与 Bailey J（观鸟，Lv.11）。按顺序找到他们，逐个解锁各系统。',
      'dbnpcs.guide.g2.h': '🎁 喜欢的礼物 = 快速涨好感',
      'dbnpcs.guide.g2.p': '每位 NPC 都有喜欢的物品清单。每天送礼提升好感度，进而解锁个人剧情和额外福利。送出稀有物品前，务必先查看「喜好礼物」一栏。',
      'dbnpcs.guide.g3.h': '🛒 商人 &amp; 服务型 NPC',
      'dbnpcs.guide.g3.p': 'Albert Jr. 高价收购你的货物（全地图游走），Ka Ching 出售背包扩容折扣，Dorothy 每天发布约 7,000 金币的食物任务。跑图时顺路拜访。',
      'dbnpcs.guide.w.h3': '📍 去哪里找',
      'dbnpcs.guide.town.h': '🏙️ 城镇中心',
      'dbnpcs.guide.town.p': '最热闹的核心区域：Massimo（咖啡馆）、Naniwa、Bailey J、Annie、Atara、收藏家与 Dorothy（服装店）都在此，全天可找。多数都在广场附近步行可达。',
      'dbnpcs.guide.suburb.h': '🏡 郊区 &amp; 花园街',
      'dbnpcs.guide.suburb.p': 'Blanc（花园街）、Ka Ching（西部郊区）、Andrew（城镇东侧）与 Bob（中心商店街）负责种田与购物相关服务，全天可找。',
      'dbnpcs.guide.out.h': '🏖️ 外围区域',
      'dbnpcs.guide.out.p': '居民分布全岛：Eric（温泉山）、Will（花田）、Patti（森林岛）、Vernie（紫罗兰海滩）、Bill（渔村）与 Doris（艺术街）。Albert Jr. 无固定位置，全地图随机游走。',
      'dbnpcs.guide.gift.h3': '🎁 送礼与好感度',
      'dbnpcs.guide.loved.h': '❤️ 喜欢 vs 最爱礼物',
      'dbnpcs.guide.loved.p': '最爱的礼物好感度加成最高。性价比之王：烤蘑菇、蓝莓酱与炸鱼薯条同时被多位 NPC 喜爱——批量做好后挨个送。',
      'dbnpcs.guide.daily.h': '⏰ 每天送礼',
      'dbnpcs.guide.daily.p': '好感度一次一涨，把送礼纳入每日循环。导师尤其会随着时间回报你——新食谱、新工具与升级福利。',
      'dbnpcs.guide.reward.h': '🏆 好感度奖励',
