      'dbnpcs.guide.hv.r2.name': 'Blanc', 'dbnpcs.guide.hv.r2.role': '园艺导师', 'dbnpcs.guide.hv.r2.unlock': 'DG Lv.3', 'dbnpcs.guide.hv.r2.why': '解锁园艺；买土豆种子——新手最佳作物（收益是番茄的 3 倍）。',
