      'money.routine.h2': '10 分钟高效赚钱循环',
      'money.routine.intro': '适合每天登录后执行的标准化流程，预计收益 8,000-15,000 金币/轮',
      'money.routine.t1.h': '① 早晨：收菜 + 播种（~2分钟）',
      'money.routine.t1.p': '收土豆/小麦/玉米，重新播种。优先种土豆（收益是番茄的3倍）和小麦（后期所有高利润食谱的核心原料）。蓝莓和草莓有种子就种。',
      'money.routine.t2.h': '② 采集：免费食材扫荡（~2分钟）',
      'money.routine.t2.p': '跑图收集浆果、蘑菇、水果、香草。秋天重点找黑松露（售价200G/个，烹饪后利润翻3-4倍）。<strong>免费=零成本=100%纯利润。</strong>',
      'money.routine.t3.h': '③ 钓鱼：高价值筛选（~3分钟）',
      'money.routine.t3.p': '去海洋钓高价值鱼（金枪鱼300+、河豚450）。≤100G 的低价值鱼（沙丁鱼、鲫鱼、鲈鱼）留作烹饪材料。<strong>记住阈值：100金币以上直接卖，以下拿去烹饪。</strong>',
      'money.routine.t4.h': '④ 烹饪：四灶批量生产（~3分钟）',
      'money.routine.t4.p': '4个炉灶围正方形，站中间同时管理4个菜品。优先批量生产：果酱（水果→170G+）+ 炸鱼薯条（鱼+土豆→310G）+ 蔬菜杂烩（蔬菜×3→200G）。',
      'money.routine.t5.h': '⑤ 出售 + 居民任务（~2分钟）',
      'money.routine.t5.p': '找到流浪商人 Albert Jr. 批量卖出所有成品。顺手完成 5 个居民任务——每个任务额外奖励 1,000-3,000 金币 + 许愿星 + 贡献勋章。',
      'money.rule.c1.h': '🔬 为什么加工比卖原料赚？',
      'money.rule.c1.p': '\n        蓝莓 ×4 直接卖 = <strong>64 金币</strong><br>\n        做成蓝莓酱 = <strong>170-320 金币</strong><br>\n        <span style="color:var(--green)">利润翻 2.7-5 倍</span>\n      ',
      'money.rule.c2.h': '🐟 鱼的分水岭：100金币',
      'money.rule.c2.p': '\n        沙丁鱼 40G → 拿去做炸鱼薯条卖 310G<br>\n        金枪鱼 300G → 直接卖，烹饪反而亏<br>\n        <span style="color:var(--green)">关键阈值记住 100G</span>\n      ',
      'money.rule.c3.h': '🌾 小麦 = 经济引擎',
      'money.rule.c3.p': '\n        黑松露意面、海鲜披萨、炸鱼薯条<br>\n        几乎所有高端食谱都消耗小麦<br>\n        <span style="color:var(--green)">睡前必种，4小时一茬</span>\n      ',
      'money.rule.eyebrow': '核心原则',
      'money.rule.h2': '赚钱黄金法则',
      'money.rule.rules': '\n    <strong>💰 铁律三条：</strong>❶ 100金币以上的鱼直接卖，≤100的拿去烹饪 &nbsp; ❷ 水果做酱、蔬菜做菜，永远不卖原料 &nbsp; ❸ 小麦是经济命脉，能种就种\n  ',
      'money.star.eyebrow': '许愿星经济',
      'money.star.h2': '⭐ 许愿星怎么花最划算',
      'money.star.intro': '许愿星是游戏中最稀缺的货币——用错地方代价巨大',
      'money.star.priority.h3': '🏅 许愿星消费优先级（从高到低）',
      'money.star.priority.p1.h': '🥇 第一优先：背包 & 仓库扩容（前5次）',
      'money.star.priority.p1.p': '前5次背包+10格、仓库+50格各仅需 <strong>10 许愿星</strong>（原价25）。这是全游戏最值的投资——背包空间直接影响生产效率。第6次起涨到25星，性价比骤降。<br><span style="color:var(--green)">建议：尽早买满前5次 = 50星换 +50背包 +250仓库。</span>',
      'money.star.priority.p2.h': '🥈 第二优先：爱好解锁 & 升级',
      'money.star.priority.p2.p': '钓鱼(Lv.2)、园艺(Lv.3)、烹饪(Lv.5)三大赚钱爱好必须优先解锁。捕虫(Lv.5/8/11)和宠物(Lv.12/14)放后面——它们不直接产生金币。<br><span style="color:var(--green)">烹饪爱好等级越高→出高品质菜概率越大→同样材料多赚50-100%。</span>',
      'money.star.priority.p3.h': '🥉 第三优先：建筑 & 装饰（功能性）',
      'money.star.priority.p3.p': '额外炉灶（多一个灶=烹饪效率×1.3）、更多田地（作物产量↑）、功能性家具。这些直接提升赚钱效率。<br><span style="color:var(--green)">装饰性家具优先级最低——好看但不产出金币。</span>',
      'money.star.priority.p4.h': '💡 急用钱技巧：许愿星 → 冲天炮 → 1100G',
      'money.star.priority.p4.p': '1个许愿星买冲天炮→卖给 Albert Jr. = <strong>1,100 金币</strong>。急用钱时的快速套现方法——不过长期来看，许愿星比金币珍贵得多，<strong>不建议频繁使用</strong>。',
      'money.star.priority.p5.h': '⚠️ 绝对不要花许愿星的地方',
      'money.star.priority.p5.p': '❌ 加速作物生长（等2小时不值1个许愿星）&nbsp; ❌ 购买基础原料（种/钓/采集免费）&nbsp; ❌ 纯装饰物品（后期有多余再买）',
