      'prog.backpack.free.total': '\n        <strong>📊 免费扩容总计：</strong>5 次 × 50 格 = <strong>+250 仓库格</strong>。这部分不需要任何操作，到达对应 DG 等级自动获得。加上初始容量，纯免费可达约 300-350 仓库格。\n      ',
