      'prog.backpack.kaChing': '\n      <strong>📍 Ka Ching 位置：</strong>西北郊区，8 号地块对面。这个 NPC 专门负责背包和仓库扩容交易。注意：背包扩容和仓库扩容是<strong>两个独立的购买项</strong>——你需要分别购买，折扣次数也是分开计算的。建议背包和仓库各买满 5 次折扣（各 50 星）后再考虑其他消费。\n    ',
