      'prog.hobbies.tips.bird.body': '\n          • <strong>重复拍同一只鸟也能累积进度</strong>——不需要追新品种<br>\n          • 找个鸟类固定出没点，安心刷等级<br>\n          • 不同时间段鸟类活动不同（清晨和黄昏种类最多）<br>\n          • 特殊天气（彩虹天）稀有鸟类出现率大幅提升\n        ',
      'prog.hobbies.tips.bird.heading': '🔭 观鸟升级',
      'prog.hobbies.tips.bug.body': '\n          • 使用充气诱捕器集中刷虫（放在昆虫密集区域）<br>\n          • 不同季节/天气出现不同昆虫<br>\n          • 高星级昆虫标本用于家园评分<br>\n          • 捕虫商店可买拼图梦（Lv.16后用于升级Dream）\n        ',
      'prog.hobbies.tips.bug.heading': '🦋 捕虫升级',
      'prog.hobbies.tips.cooking.body': '\n          • <strong>四灶烹饪法</strong>：4个炉灶围成正方形，角色站中间同时管理4个菜<br>\n          • 批量做同一种菜品，效率最大化<br>\n          • 优先做高价值配方：蓝莓酱、炸鱼薯条、炸鲫鱼<br>\n          • 烹饪等级 = 高星概率 ↑ = 售价 ↑ = 赚钱效率 ↑\n        ',
      'prog.hobbies.tips.cooking.heading': '🍳 烹饪升级',
      'prog.hobbies.tips.fishing.body': '\n          • 高价值钓点优先：海洋（夏季）> 河流 > 池塘<br>\n          • 海上钓鱼活动周是快速冲级的最佳时机<br>\n          • 不同天气去不同钓点：晴天海钓、雨天河钓<br>\n          • <strong>钓鱼等级越高 → 高星鱼概率越大 → 售价越高</strong>\n        ',
      'prog.hobbies.tips.fishing.heading': '🎣 钓鱼升级',
      'prog.hobbies.tips.gardening.body': '\n          • 多种快熟作物轮作（土豆 2h）→ 高频收获 = 高频经验<br>\n          • 保持田地不空置——收了就种<br>\n          • 高品质花卉（玫瑰、百合）额外贡献家园评分<br>\n          • <strong>园艺等级影响作物星级和产量</strong>\n        ',
      'prog.hobbies.tips.gardening.heading': '🌱 园艺升级',
      'prog.hobbies.tips.heading': '📈 各爱好升级技巧',
      'prog.hobbies.tips.pets.body': '\n          • 每日互动（喂食、抚摸、玩耍）积累好感度<br>\n          • 完成猫护理基础教程后才能解锁养狗<br>\n          • 猫狗可同时养——两只宠物好感度独立计算<br>\n          • 宠物好感度提升 → 解锁新互动 → 家园评分加成\n        ',
      'prog.hobbies.tips.pets.heading': '🐱🐕 宠物升级',
      'prog.house.advanced.heading': '🎨 DG 15+：高级建造的装修策略',
      'prog.house.advanced.p1': '\n          高级建造解锁后，你终于可以高效地进行真正的室内设计了。建议按以下顺序推进：\n        ',
      'prog.house.advanced.p2': '\n          <strong>高级建造装修流程：</strong><br>\n          ① <strong>先做平面图：</strong>确定每个房间的功能（厨房区、卧室区、收藏展示区、宠物区）<br>\n          ② <strong>墙壁和地板：</strong>批量铺设地板 → 批量建墙隔出房间 → 调整屋顶尺寸<br>\n          ③ <strong>多屋顶设计：</strong>不同区域使用不同高度/角度的屋顶，避免"一个长方形盒子"的平面感<br>\n          ④ <strong>家具布置：</strong>按功能区放置家具，利用高级模式的精确角度旋转<br>\n          ⑤ <strong>装饰收尾：</strong>挂画、摆件、植物、灯光——这些细节决定品质感\n        ',
      'prog.house.advanced.p3': '\n          <strong>核心原则：</strong>高级建造的撤销功能很完善——大胆实验不同布局，不满意就撤销重来。多去好友家参观，截图记录灵感。\n        ',
      'prog.house.blueprint.heading': '🏗️ DG 4-14：蓝图模式的正确用法',
      'prog.house.blueprint.p1': '\n          在解锁高级建造之前（DG 4-14），<strong>不要把大量时间花在装修上</strong>。蓝图模式效率低，你现在花 2 小时摆的墙，到了 Lv.15 用高级模式 10 分钟就能搞定——而且效果更好。\n        ',
      'prog.house.blueprint.p2': '\n          <strong>蓝图阶段只做这些：</strong><br>\n          ① 放置功能家具：床、炉灶（4个围成正方形）、储物箱、工作台<br>\n          ② 保持房屋空旷——给自己留出未来设计的空间<br>\n          ③ 可以画平面设计图（纸上或截图标注），但不要施工<br>\n          ④ 收集灵感：访问好友家园、截图喜欢的布局\n        ',
      'prog.house.blueprint.p3': '\n          <strong>核心原则：</strong>蓝图阶段的所有金币和精力投入生产工具（种子、炉灶、扩容），不投入纯装饰。等 Lv.15 高级建造解锁后再全面启动装修计划。\n        ',
      'prog.house.compare.heading': '🔷 蓝图模式 vs 高级建造模式',
