      'prog.house.eyebrow': '家园系统',
      'prog.house.heading': '🏠 房屋建造系统 · 详解',
      'prog.house.intro': 'Heartopia 的建造系统分两个阶段：基础蓝图模式（DG Lv.4）和高级建造模式（DG Lv.15）。两个模式的能力差距巨大——了解差异能帮你避免在低效模式下浪费大量时间。',
      'prog.house.tips.heading': '💡 房屋建造进阶技巧',
      'prog.house.tips.iter.body': '\n          ① 用蓝图模式先搭"框架"——墙壁位置和房间大小<br>\n          ② 走进去感受空间比例——太大了空旷、太小了拥挤<br>\n          ③ 高级建造撤销重做——直到空间比例舒适为止<br>\n          ④ 最后添加家具和装饰——细节是最后一步<br>\n          <strong>不要一次定稿——好设计是改出来的。</strong>\n        ',
      'prog.house.tips.iter.heading': '🔄 迭代设计法',
      'prog.house.tips.open.body': '\n          <strong>开放式</strong>（少墙/无墙）：空间感强、适合展示大型收藏品、视野开阔。适合新手——少墙 = 少犯错。<br>\n          <strong>隔间式</strong>（多房间）：功能区明确、私密感强、适合主题化设计（厨房、书房、阳光房）。需要高级建造的批量隔墙能力。\n        ',
      'prog.house.tips.open.heading': '🏗️ 开放式 vs 隔间式',
      'prog.house.tips.roof.body': '\n          ① <strong>多屋顶拼接：</strong>不同区域用不同高度/坡度的屋顶 → 打破"方盒子"感<br>\n          ② <strong>屋顶颜色搭配：</strong>与外墙颜色协调，深色屋顶 + 浅色墙壁 = 经典组合<br>\n          ③ <strong>天窗效果：</strong>部分区域留空屋顶 → 自然光洒入 → 空间感倍增\n        ',
      'prog.house.tips.roof.heading': '📐 屋顶设计技巧',
      'prog.house.tips.score.body': '\n          家园评分 = <strong>家具品质 + 稀有收藏品 + 高级花卉</strong><br>\n          • 放置 5 星收藏品（昆虫标本、稀有鱼类标本）<br>\n          • 高级花卉：玫瑰、百合 > 基础花卉<br>\n          • 雕塑和特殊家具评分远高于普通家具<br>\n          • 2000+ 可交互组件自由搭配\n        ',
      'prog.house.tips.score.heading': '⭐ 家园评分提升',
