      'prog.pets.faq.a1': '<strong>不可以。</strong>猫护理基础教程是养狗的硬性前置条件。你必须在 DG Lv.12 解锁猫 → 收养猫 → 完成护理教程 → 才能在 DG Lv.14 解锁狗。这是游戏设定的不可跳过的顺序。',
      'prog.pets.faq.a2': '<strong>可以！</strong>解锁狗之后，一只猫和一只狗可以同时在你的家园生活。它们各自有独立的互动项和好感度条，互不影响。建议每天先互动猫（简单），再互动狗（需要遛狗，多花时间）。',
      'prog.pets.faq.a3': '宠物的<strong>好感度不会因为断食而下降</strong>。如果你某天忘了喂食或互动，不会受到惩罚——只是那天没有积累新的好感度而已。这让宠物系统对不每天登录的轻度玩家很友好。',
