      'prog.pets.sequence.s3.body': '在等待 DG Lv.14 的期间，每天与猫咪互动积累好感度。猫咪的好感度等级不会因为后面养狗而重置——两只宠物的进度<strong>完全独立</strong>。建议在解锁狗之前把猫的好感度升到至少 2-3 级。',
